-- Independent reference-guided studies; no image input. Run: --script-param out=<dir> --script draw.lua
local out=assert(app.params.out)
local palette={ink='382b2a',dark='47332f',hair='684839',hlight='865b44',skin='ffb683',shadow='cd815b',blush='e89a6c',white='f8e7d2',eye='3f2b28',brown='754632',tie='e8d8b9',oliveink='383d30',olive='636546',olivelt='777950',olivesh='484d36',tee='f7e2cf',teesh='c9b7b8',bag='f0ccb0',bagsh='bd927d'}
local c={} for k,v in pairs(palette) do c[k]=app.pixelColor.rgba(tonumber(v:sub(1,2),16),tonumber(v:sub(3,4),16),tonumber(v:sub(5,6),16),255) end
local function build(name,w,h,parts)
 local s=Sprite(w,h,ColorMode.RGB); s:deleteLayer(s.layers[1])
 for _,part in ipairs(parts) do
  -- Recompose head shapes around the neck junction, at native coordinates.
  -- This is a structural pass on the independently authored first pass, not an image resize.
  local ishead=part[1]=='Back hair' or part[1]=='Neck and face' or part[1]=='Features' or part[1]=='Front hair'
  if ishead then
   local cx,cy,scale = w==120 and 62 or 83, w==120 and 70 or 94, .76
   for i=2,#part do for _,pt in ipairs(part[i][2]) do pt[1]=math.floor(cx+(pt[1]-cx)*scale+.5);pt[2]=math.floor(cy+(pt[2]-cy)*scale+.5) end end
  end
  if part[1]=='Back hair' then
   if w==120 then
    table.insert(part,{'hair',{{26,49},{30,44},{34,42},{33,49},{29,54},{25,55}}})
    table.insert(part,{'hlight',{{26,44},{30,40},{33,39},{31,42},{28,45}}})
    table.insert(part,{'dark',{{24,51},{26,54},{31,55},{29,58},{25,57},{22,53}}})
   else
    table.insert(part,{'hair',{{35,66},{39,59},{45,55},{44,64},{39,70},{33,72}}})
    table.insert(part,{'hlight',{{34,59},{39,53},{43,52},{41,56},{36,61}}})
    table.insert(part,{'dark',{{32,69},{35,73},{41,74},{38,77},{33,76},{30,71}}})
   end
  end
  local layer=s:newLayer();layer.name=part[1];local im=Image(w,h,ColorMode.RGB)
  local function pixel(x,y,col) if x>=0 and y>=0 and x<w and y<h then im:drawPixel(x,y,c[col]) end end
  local function segment(a,b,col) local x,y=a[1],a[2];local dx,dy=math.abs(b[1]-x),-math.abs(b[2]-y);local sx=x<b[1] and 1 or -1;local sy=y<b[2] and 1 or -1;local e=dx+dy while true do pixel(x,y,col);if x==b[1] and y==b[2] then break end; local z=2*e;if z>=dy then e=e+dy;x=x+sx end;if z<=dx then e=e+dx;y=y+sy end end end
  for i=2,#part do local p=part[i];local pts=p[2];local ymin,ymax=h,0;for _,v in ipairs(pts) do ymin=math.min(ymin,v[2]);ymax=math.max(ymax,v[2]) end
   for y=ymin,ymax do local hits={};for j=1,#pts do local a,b=pts[j],pts[j%#pts+1];if (a[2]<=y+.5 and b[2]>y+.5) or (b[2]<=y+.5 and a[2]>y+.5) then hits[#hits+1]=a[1]+(y+.5-a[2])*(b[1]-a[1])/(b[2]-a[2]) end end;table.sort(hits);for j=1,#hits-1,2 do for x=math.ceil(hits[j]-.5),math.floor(hits[j+1]-.5) do pixel(x,y,p[1]) end end end
   if p[3] then for j=1,#pts do segment(pts[j],pts[j%#pts+1],p[3]) end end
  end
  s:newCel(layer,1,im,Point(0,0))
 end
 s:saveAs(out..'/'..name..'.aseprite');s:saveCopyAs(out..'/'..name..'.png');s:close()
end
